/bin/zsh -lc "python3 -B - <<'PY'
from pathlib import Path
for name in ('batch', 'recount', 'availability', 'preview'):
    scope = {}
    path = Path('repos/reader') / (name + '.py')
    exec(compile(path.read_text(), str(path), 'exec'), scope)
    if name == 'recount':
        result = scope['recount_available'](10, {'reserved_milliunits': 1500})
    elif name == 'preview':
        result = scope['preview'](10, 1.5)
    else:
        result = scope['available'](10, 1500)
    print(f'{path}: available={result}; expected=8.5')
PY"
